/**
 * Client-safe map helpers. Deliberately imports no data: anything a `"use
 * client"` component needs lives here, so the 1,200-line dataset in
 * `@/lib/maps` never gets pulled into a browser bundle.
 */

export type MapItem = {
	id: string;
	name: string;
	imageUrl: string;
	description: string;
	/** Category heading this map sits under; set by the ordering in `@/lib/maps`. */
	group?: string;
};

export type AreaSummary = {
	slug: string;
	name: string;
	count: number;
};

/** Card-sized webp generated by `pnpm img`, mirroring /maps under /thumbs. */
export const thumbUrl = (imageUrl: string) =>
	imageUrl.replace(/^\/maps\//, "/thumbs/").replace(/\.[^.]+$/, ".webp");

/**
 * Short chip label for the footer index, the way shivaassociates.co label
 * theirs: the fifteen "SECTOR 18 PART-…" sheets all collapse to "Sector 18",
 * ALPHA-I and ALPHA-II to "Alpha", "VILLAGE ACHEJA BUJARG" to "Village Acheja".
 * Raw plan names made the strip a wall of near-identical text.
 */

/** Everything from here on is a part number, a block or a qualifier. */
const TAIL =
	/[\s-]+(?:I{1,3}|IV|VI{0,3}|IX|XI{0,2}|X|\d+[A-Z]?|PART|POCKET|PKT|BLOCK|EXTENSION|EXTN?|PHASE|SECTOR|UDYOG|SITE|AND)\b/;

const SKIP = new Set([
	"ABADI",
	"VILLAGE",
	"VILL",
	"AT",
	"OF",
	"THE",
	"EXPANSION",
	"EXTENSION",
	"LAYOUT",
	"PLAN",
	"GROUP",
	"HOUSING",
	"PART",
	"POCKET",
]);

const title = (s: string) =>
	s
		.toLowerCase()
		.replace(/\b[a-z]/g, (c) => c.toUpperCase())
		.replace(/\bOf\b|\bAnd\b|\bAt\b/g, (w) => w.toLowerCase());

export function tagLabel(name: string): string {
	const n = name
		.toUpperCase()
		.replace(/\([^)]*\)/g, " ")
		.replace(/\s+/g, " ")
		.trim();

	const sector = n.match(/^(?:(?:PART|POCKET)\s+)?SECTOR[\s-]*(\d+)/);
	if (sector) return `Sector ${sector[1]}`;
	if (/^\d+\s*PERCENT/.test(n)) return "7% residential plots";
	if (/^MASTER PLAN/.test(n)) return "Master plan";

	if (/\b(?:ABADI|VILLAGE|VILL\.)\b/.test(n)) {
		const word = n
			.split(/[\s-]+/)
			.find((w) => w.length > 1 && !SKIP.has(w.replace(/\./g, "")));
		if (word) return `Village ${title(word)}`;
	}

	return title(n.split(TAIL)[0].trim() || n);
}
